// Learn hub content: outside resources (channels, books, papers, courses, tools), strategy cards with what published
// research found, a glossary and a learning path. Links only; nothing here is fetched or advice. Book links go to an Open
// Library search and some papers to a Google Scholar search, so a link never points at a guessed edition or ID.
// Studies are summarised in plain words with the paper named; numbers are only quoted where the paper states them.

export type Topic = 'start' | 'strategies' | 'technical' | 'fundamentals' | 'markets' | 'psychology' | 'fund' | 'ai';
export type Kind = 'Channel' | 'Video' | 'Course' | 'Book' | 'Paper' | 'Article' | 'Podcast' | 'Tool' | 'Game' | 'Puzzle' | 'PDF';
export type Tag = 'Educator' | 'Practitioner' | 'Academic' | 'Sells courses' | 'Fund' | 'Free';

export interface Resource { id: string; title: string; by: string; kind: Kind; url: string; why: string; topics: Topic[]; tags?: Tag[] }

export const TOPICS: { id: Topic; label: string; blurb: string }[] = [
  { id: 'start', label: 'Start here', blurb: 'How the stock market works, the learning path and the basics to know before risking money.' },
  { id: 'strategies', label: 'Strategies', blurb: 'Each strategy: how it works, why it might work, what published history shows, who trades it, how to try it on the desk and how it fails.' },
  { id: 'technical', label: 'Technical', blurb: 'Price action, patterns, indicators and market structure, plus the research on which of it holds up.' },
  { id: 'fundamentals', label: 'Fundamentals', blurb: 'What sets a price: earnings, cash flow, discount rates, filings and the calendar that moves stocks.' },
  { id: 'markets', label: 'How prices move', blurb: 'Order books, market makers, flows, options hedging and index funds: the plumbing behind every move.' },
  { id: 'psychology', label: 'Psychology', blurb: 'What the data says about traders, the biases that cost money, and routines that help.' },
  { id: 'fund', label: 'Think like a fund', blurb: 'How hedge-fund researchers and traders form, test, size and review an idea.' },
  { id: 'ai', label: 'AI for trading', blurb: 'Using Claude and other models for research, where they go wrong, and machine learning in finance.' },
];

const yt = (h: string) => `https://www.youtube.com/@${h}`;
const book = (title: string, author: string) => `https://openlibrary.org/search?q=${encodeURIComponent(`${title} ${author}`)}`;
const sch = (q: string) => `https://scholar.google.com/scholar?q=${encodeURIComponent(q)}`;

