/* ---------------- glossary ---------------- */
export const GLOSSARY: { term: string; def: string; topic: Topic }[] = [
  { term: 'Bid / ask', def: 'The best price someone will buy at (bid) and sell at (ask). The difference is the spread, a cost every time you trade.', topic: 'markets' },
  { term: 'Market order', def: 'Buy or sell now at whatever price is available. Fast, but you pay the spread and can get a bad fill in thin markets.', topic: 'markets' },
  { term: 'Limit order', def: 'Buy or sell only at your price or better. You control the price but may not get filled.', topic: 'markets' },
  { term: 'Stop order', def: 'Becomes a market order once a price is touched; used to cap a loss. Can fill far worse after a gap.', topic: 'markets' },
  { term: 'Liquidity', def: 'How easily you can trade size without moving the price. Tight spreads and deep order books mean high liquidity.', topic: 'markets' },
  { term: 'Slippage', def: 'The difference between the price you expected and the price you got.', topic: 'markets' },
  { term: 'Market maker', def: 'A firm that quotes both a bid and an ask, earning the spread and managing the inventory risk.', topic: 'markets' },
  { term: 'Payment for order flow', def: 'Brokers sending customer orders to market makers who pay for them; the market maker profits from filling them.', topic: 'markets' },
  { term: 'Dark pool', def: 'A private venue where trades are matched without showing orders publicly beforehand.', topic: 'markets' },
  { term: 'Short selling', def: 'Borrowing shares to sell now, hoping to buy them back cheaper. Losses are unlimited if the price rises.', topic: 'markets' },
  { term: 'Short squeeze', def: 'A rise that forces short sellers to buy back, which pushes the price higher still.', topic: 'markets' },
  { term: 'Float', def: 'Shares available for public trading, excluding those held by insiders and locked up.', topic: 'markets' },
  { term: 'Volume', def: 'Shares traded in a period. Moves on high volume carry more conviction than moves on low volume.', topic: 'technical' },
  { term: 'Relative volume', def: 'Today’s volume compared with the normal volume for this time of day.', topic: 'technical' },
  { term: 'Support / resistance', def: 'Price areas where buying (support) or selling (resistance) has repeatedly appeared.', topic: 'technical' },
  { term: 'Trend', def: 'A run of higher highs and higher lows (uptrend) or lower highs and lower lows (downtrend).', topic: 'technical' },
  { term: 'Moving average', def: 'The average closing price over the last N bars; smooths noise and shows trend direction.', topic: 'technical' },
  { term: 'VWAP', def: 'Volume-weighted average price for the session: the average price paid per share today.', topic: 'technical' },
  { term: 'RSI', def: 'Relative Strength Index: a 0–100 measure of recent gains versus losses. Low readings mean recently oversold.', topic: 'technical' },
  { term: 'ATR', def: 'Average True Range: the typical size of a bar, used to set stops and position sizes that fit the volatility.', topic: 'technical' },
  { term: 'Gap', def: 'When a bar opens above the previous high or below the previous low, leaving a price range with no trades.', topic: 'technical' },
  { term: 'Breakout', def: 'Price moving decisively out of a range or past a key level.', topic: 'technical' },
  { term: 'Divergence', def: 'Price makes a new high or low but an indicator does not; a possible sign the move is tiring.', topic: 'technical' },
  { term: 'Candlestick', def: 'A bar showing open, high, low and close; the body is open-to-close, the wicks are the extremes.', topic: 'technical' },
  { term: 'EPS', def: 'Earnings per share: net profit divided by shares outstanding.', topic: 'fundamentals' },
  { term: 'P/E ratio', def: 'Price divided by earnings per share: how many years of current earnings you pay for.', topic: 'fundamentals' },
  { term: 'Free cash flow', def: 'Cash from operations minus capital spending: the cash a business could return to owners.', topic: 'fundamentals' },
  { term: 'Gross margin', def: 'Revenue minus the direct cost of goods, as a share of revenue.', topic: 'fundamentals' },
  { term: 'Discount rate', def: 'The return investors require; higher rates make future cash flows worth less today, so prices fall.', topic: 'fundamentals' },
  { term: 'Guidance', def: 'A company’s own forecast for coming quarters. Often moves the stock more than the reported results.', topic: 'fundamentals' },
  { term: 'Earnings surprise', def: 'Reported results versus what analysts expected.', topic: 'fundamentals' },
  { term: '10-K / 10-Q', def: 'Annual and quarterly reports filed with the SEC: financial statements, risks and management’s discussion.', topic: 'fundamentals' },
  { term: 'Dilution', def: 'New shares issued, shrinking each existing shareholder’s slice.', topic: 'fundamentals' },
  { term: 'Buyback', def: 'A company buying its own shares, reducing the share count.', topic: 'fundamentals' },
  { term: 'Implied volatility', def: 'The volatility the options market is pricing in; high IV means expensive options.', topic: 'strategies' },
  { term: 'IV crush', def: 'The drop in implied volatility after an event like earnings, which deflates option prices.', topic: 'strategies' },
  { term: 'Delta', def: 'How much an option’s price changes for a $1 move in the stock.', topic: 'strategies' },
  { term: 'Gamma', def: 'How fast delta changes. Dealers’ gamma exposure affects whether their hedging calms or amplifies moves.', topic: 'strategies' },
  { term: 'Theta', def: 'How much value an option loses per day from time passing.', topic: 'strategies' },
  { term: 'Open interest', def: 'The number of option contracts currently open at a strike.', topic: 'strategies' },
  { term: 'Expected move', def: 'The range the options market implies for a stock by a date, from implied volatility.', topic: 'strategies' },
  { term: 'Factor', def: 'A shared trait (value, momentum, quality, size, low volatility) that explains why groups of stocks move together.', topic: 'strategies' },
  { term: 'Beta', def: 'How much a stock tends to move with the market. Beta 1.5 means roughly 1.5 times the market’s moves.', topic: 'fund' },
  { term: 'Alpha', def: 'Return beyond what market and factor exposure explain: the part attributed to skill.', topic: 'fund' },
  { term: 'Sharpe ratio', def: 'Return above cash divided by volatility: return per unit of risk.', topic: 'fund' },
  { term: 'Drawdown', def: 'The fall from a peak in account value to the next low.', topic: 'fund' },
  { term: 'Expected value', def: 'Average outcome per trade: win rate times average win minus loss rate times average loss.', topic: 'fund' },
  { term: 'R-multiple', def: 'Profit or loss measured in units of the risk you took. A +2R trade made twice what you risked.', topic: 'fund' },
  { term: 'Position sizing', def: 'Deciding how much to trade so that being wrong costs a set, survivable amount.', topic: 'fund' },
  { term: 'Kelly criterion', def: 'A formula for the bet size that maximises long-run growth; traders usually use a fraction of it.', topic: 'fund' },
  { term: 'Variant perception', def: 'A view that differs from the consensus and that you can explain: who is wrong, why, and what will show it.', topic: 'fund' },
  { term: 'Catalyst', def: 'An event that could make the market change its mind: earnings, a ruling, a product launch.', topic: 'fund' },
  { term: 'Base rate', def: 'How often something happens in general, before looking at the specifics of this case.', topic: 'fund' },
  { term: 'Pre-mortem', def: 'Imagining the trade has already failed and listing why, before entering.', topic: 'fund' },
  { term: 'Overfitting', def: 'Tuning a strategy so closely to past data that it captures noise and fails on new data.', topic: 'ai' },
  { term: 'Look-ahead bias', def: 'A backtest accidentally using information that was not available at the time.', topic: 'ai' },
  { term: 'Survivorship bias', def: 'Testing only on stocks that still exist, ignoring those that went bust; it flatters results.', topic: 'ai' },
  { term: 'Out-of-sample test', def: 'Checking a strategy on data it was not designed on.', topic: 'ai' },
  { term: 'Hallucination', def: 'An AI model stating something false with confidence, such as a made-up number or source.', topic: 'ai' },
  { term: 'Loss aversion', def: 'Losses hurt roughly twice as much as equal gains please, which makes people hold losers and sell winners.', topic: 'psychology' },
  { term: 'Disposition effect', def: 'The tendency to sell winners too early and hold losers too long.', topic: 'psychology' },
  { term: 'Revenge trading', def: 'Trading bigger or faster right after a loss to win it back.', topic: 'psychology' },
  { term: 'Overconfidence', def: 'Overrating your own skill, especially after a run of wins; leads to over-trading and over-sizing.', topic: 'psychology' },
  { term: 'Confirmation bias', def: 'Seeking out information that supports what you already believe.', topic: 'psychology' },
  { term: 'Recency bias', def: 'Giving the last few days or trades far more weight than the longer record.', topic: 'psychology' },
];

