export const resourceById = (id: string) => RESOURCES.find((r) => r.id === id);

/** Library search: every word must appear somewhere in the title, author, description, kind or tags. */
export function searchResources(q: string, list: Resource[] = RESOURCES): Resource[] {
  const words = q.toLowerCase().split(/\s+/).filter(Boolean);
  if (!words.length) return list;
  return list.filter((r) => { const hay = `${r.title} ${r.by} ${r.why} ${r.kind} ${(r.tags ?? []).join(' ')} ${r.topics.join(' ')}`.toLowerCase(); return words.every((w) => hay.includes(w)); });
}
